#!/usr/bin/env python3
"""
CLI tool to summarize log levels in .log files.

Usage:
    python log_summary.py /path/to/logs --min-errors 3
"""

import argparse
import re
import sys
from pathlib import Path

LOG_LEVELS = ("INFO", "WARN", "ERROR", "DEBUG")

# Match whole words only, so e.g. "WARNING" is not counted as "WARN".
LEVEL_PATTERNS = {
    level: re.compile(rf"\b{level}\b", re.IGNORECASE)
    for level in LOG_LEVELS
}


def count_log_levels(path: Path) -> dict:
    """
    Count log level occurrences in a single file.

    A line is counted for a level if the level appears as a standalone word.
    If a line contains multiple level words, each is counted.
    """
    counts = {level: 0 for level in LOG_LEVELS}

    try:
        with path.open("r", encoding="utf-8", errors="replace") as f:
            for line in f:
                for level, pattern in LEVEL_PATTERNS.items():
                    if pattern.search(line):
                        counts[level] += 1
    except OSError as exc:
        print(f"Warning: could not read {path}: {exc}", file=sys.stderr)

    return counts


def find_log_files(directory: Path) -> list:
    """Return sorted .log files directly inside the given directory."""
    files = []
    for path in directory.iterdir():
        if path.is_file() and path.suffix.lower() == ".log":
            files.append(path)
    return sorted(files, key=lambda p: p.name)


def format_table(rows: list) -> str:
    """
    Format rows into a simple aligned table.

    rows: list of tuples:
        (filename, {"INFO": int, "WARN": int, "ERROR": int, "DEBUG": int})
    """
    if not rows:
        return ""

    file_width = max(len("FILE"), max(len(name) for name, _ in rows))
    level_widths = {
        level: max(
            len(level),
            max((len(str(counts[level])) for _, counts in rows), default=0)
        )
        for level in LOG_LEVELS
    }

    def make_row(name: str, counts: dict) -> str:
        parts = [name.ljust(file_width)]
        for level in LOG_LEVELS:
            parts.append(str(counts[level]).rjust(level_widths[level]))
        return " | ".join(parts)

    lines = []
    header_parts = ["FILE".ljust(file_width)]
    for level in LOG_LEVELS:
        header_parts.append(level.rjust(level_widths[level]))
    lines.append(" | ".join(header_parts))

    separator = "-+-".join(
        ["-" * file_width] + ["-" * level_widths[level] for level in LOG_LEVELS]
    )
    lines.append(separator)

    for name, counts in rows:
        lines.append(make_row(name, counts))

    return "\n".join(lines)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        description="Summarize INFO, WARN, ERROR, and DEBUG counts for .log files."
    )
    parser.add_argument(
        "directory",
        help="Directory containing .log files"
    )
    parser.add_argument(
        "--min-errors",
        type=int,
        default=0,
        metavar="N",
        help="Only show files with at least N ERROR occurrences (default: 0)"
    )

    args = parser.parse_args(argv)

    if args.min_errors < 0:
        parser.error("--min-errors must be zero or greater")

    directory = Path(args.directory)
    if not directory.is_dir():
        parser.error(f"not a directory: {directory}")

    log_files = find_log_files(directory)
    if not log_files:
        print("No .log files found.")
        return 0

    rows = []
    for path in log_files:
        counts = count_log_levels(path)
        if counts["ERROR"] >= args.min_errors:
            rows.append((path.name, counts))

    if not rows:
        print(f"No files with at least {args.min_errors} ERROR occurrence(s).")
        return 0

    print(format_table(rows))
    return 0


if __name__ == "__main__":
    sys.exit(main())
